property.value:
//ClassBody/MethodDeclaration[@Override = false()]
  [
    let $method := .,
        $name := @Name,
        $calls := ancestor::ClassBody[1]//MethodCall[@MethodName = $name]
                    [*[1][self::ArgumentList or self::ThisExpression]]
                    [not(ancestor::MethodDeclaration[1] is $method)]
    return exists($calls) and @BeginLine < min($calls/@BeginLine)
  ]
